});

const body: import("bharosa").HistoryImport = {
  "source": {
    "kind": "user",
    "reference": "synthetic-statement"
  },
  "holdings": [
    {
      "external_id": "example-holding",
      "investment_account": "iac_0123456789abcdef0123456789abcdef",
      "instrument": "ins_markets_scheme_101",
      "opening": {
        "date": "2026-01-01",
        "quantity": "10"
      },
      "complete_range": {
        "from": "2026-01-01",
        "through": "2026-01-31"
      },
      "transactions": [
        {
          "external_id": "buy-1",
          "date": "2026-01-03",
          "sequence": 1,
          "kind": "buy",
          "quantity": "3"
        }
      ]
    }
  ],
  "complete_range": {
    "from": "2026-01-01",
    "through": "2026-01-31"
  }
};
const idempotencyKey = crypto.randomUUID();
const result = await (await bharosa.portfolios.retrieve("ptf_0123456789abcdef0123456789abcdef")).history.import(body, { idempotencyKey });

