// Keep this fund owner and month-start date fixed throughout pagination.
async function readHoldings(fundOwnerId: string) {
  const pages = [];
  const seen = new Set<string>();
  let startingAfter: string | undefined;
  let disclosure: string | undefined;
  for (;;) {
    const result = await bharosa.mutualFunds.portfolios.holdings.list(fundOwnerId, {
      asOf: "2026-08-01", limit: 20,
      ...(startingAfter ? { startingAfter } : {}),
    });
    if (result.status === "missing") {
      if (pages.length) throw new Error("The disclosure changed. Restart the lookup.");
      return [result];
    }
    const identity = result.data.portfolio.id + ":" + result.observation_date;
    if (disclosure && disclosure !== identity) throw new Error("The disclosure changed. Restart the lookup.");
    disclosure = identity;
    // Retain every page and reject a changed disclosure instead of mixing results.
    pages.push(result);
    if (!result.data.holdings.has_more) return pages;
    const cursor = result.data.holdings.next_cursor;
    if (!cursor || seen.has(cursor)) throw new Error("Pagination did not advance. Retry the lookup.");
    seen.add(cursor);
    startingAfter = cursor;
  }
}

